"""Render a self-contained, searchable HTML compatibility report."""

from datetime import datetime
import html
import json


def escape(value):
    return html.escape(str(value if value is not None else ""), quote=True)


STYLE = r"""
:root{--bg:#090d12;--pane:#111821;--pane2:#151f29;--line:#2a3740;--text:#edf4f4;--muted:#9db0b9;--lime:#c7f36e;--blue:#91d2eb;--amber:#ffca7b;--red:#ff9c95}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--text);background:radial-gradient(circle at 92% -7%,#18353c,transparent 35%),var(--bg);font:14px/1.48 Inter,'Segoe UI',system-ui,sans-serif}button,input,select{font:inherit}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--lime);outline-offset:2px}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}.wrap{max-width:1480px;margin:auto;padding:0 28px}.top{border-bottom:1px solid var(--line);background:#0b1016d9;backdrop-filter:blur(14px);position:sticky;top:0;z-index:5}.topin{min-height:58px;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{color:var(--lime);font:800 12px Consolas,monospace;letter-spacing:.15em}.topnote{color:var(--muted);font-size:12px}.hero{padding:54px 0 36px;display:grid;grid-template-columns:1fr auto;align-items:end;gap:30px}.eyebrow{color:var(--lime);font:700 11px Consolas,monospace;letter-spacing:.16em;text-transform:uppercase}.hero h1{font-size:clamp(40px,5vw,66px);letter-spacing:-.06em;line-height:1.04;margin:12px 0 14px}.hero h1 span{color:var(--lime)}.hero p{font-size:16px;max-width:760px;color:#b7c7cc;margin:0}.heroScore{border-left:1px solid var(--line);padding-left:27px;min-width:185px}.heroScore strong{display:block;color:var(--lime);font-size:54px;letter-spacing:-.07em;line-height:1.1}.heroScore strong small{font-size:23px;color:var(--muted)}.heroScore p{font-size:12px;max-width:185px}.hardware{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:15px;overflow:hidden;margin:0 0 42px}.hardware>div{padding:19px 21px;background:var(--pane);min-width:0}.hardware label{display:block;color:var(--muted);font:700 10px Consolas,monospace;letter-spacing:.13em;text-transform:uppercase;margin-bottom:8px}.hardware b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:16px}.hardware small{display:block;color:var(--muted);margin-top:3px}.intro{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:15px}.intro h2{font-size:26px;letter-spacing:-.04em;margin:0}.intro p{max-width:595px;color:var(--muted);font-size:12px;margin:0}.notice{padding:12px 16px;background:#30271e;border:1px solid #755b3a;color:#ffd89a;border-radius:11px;margin-bottom:14px;font-size:12px}.library{display:grid;grid-template-columns:minmax(340px,.9fr) minmax(480px,1.1fr);gap:16px;align-items:start;min-height:600px}.listpane,.detailpane{background:var(--pane);border:1px solid var(--line);border-radius:17px;overflow:hidden}.listpane{min-height:640px}.listtools{padding:17px;border-bottom:1px solid var(--line)}.search{width:100%;padding:11px 13px;background:#0c1218;border:1px solid #35444d;border-radius:9px;color:var(--text);outline:0}.search::placeholder{color:#718690}.toolrow{display:flex;gap:8px;margin-top:10px}.toolrow select{min-width:0;flex:1;padding:8px 9px;border-radius:8px;background:#1b2630;color:var(--text);border:1px solid var(--line)}.listmeta{font:700 10px Consolas,monospace;color:var(--muted);letter-spacing:.12em;text-transform:uppercase;padding:12px 18px;border-bottom:1px solid var(--line)}.gamelist{max-height:660px;overflow:auto;scrollbar-color:#43545e transparent}.row{appearance:none;border:0;background:transparent;color:var(--text);width:100%;text-align:left;padding:12px 17px;display:grid;grid-template-columns:37px minmax(0,1fr) auto;align-items:center;gap:10px;border-bottom:1px solid #243039;cursor:pointer}.row:hover{background:#1b2731}.row[aria-selected=true]{background:#243529;box-shadow:inset 3px 0 var(--lime)}.rank{color:#70858e;font:700 11px Consolas,monospace}.rowtitle{min-width:0}.rowtitle b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.rowtitle small{color:var(--muted);font-size:11px}.state{font:800 10px Consolas,monospace;letter-spacing:.04em;text-transform:uppercase;border-radius:20px;padding:4px 7px;white-space:nowrap}.state.meets,.check.pass{color:var(--lime);background:#293b24}.state.review,.check.review{color:var(--amber);background:#3b3023}.state.below,.state.unavailable,.check.fail{color:var(--red);background:#3c2928}.state.na,.check.na{color:var(--muted);background:#273139}.empty{padding:25px;color:var(--muted)}.detailpane{position:sticky;top:74px;max-height:calc(100vh - 90px);overflow:auto;scrollbar-color:#43545e transparent}.cover{height:185px;background:linear-gradient(120deg,#1c3b3f,#1e252e);position:relative;overflow:hidden}.cover img{width:100%;height:100%;object-fit:cover;opacity:.72}.cover::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,var(--pane),transparent 80%)}.detailbody{padding:24px}.detailtop{display:flex;justify-content:space-between;align-items:start;gap:12px}.detailtop h2{font-size:29px;line-height:1.12;letter-spacing:-.04em;margin:5px 0 9px}.detailtop .state{margin-top:5px}.subline{color:var(--muted);font-size:12px}.desc{color:#b8c7ce;font-size:13px;margin:16px 0 21px}.tabs{display:flex;border-bottom:1px solid var(--line);gap:24px}.tab{background:none;border:0;color:var(--muted);font-size:13px;font-weight:700;padding:0 0 10px;cursor:pointer;border-bottom:2px solid transparent}.tab[aria-selected=true]{color:var(--lime);border-bottom-color:var(--lime)}.checks{display:grid;gap:8px;margin:16px 0}.check{display:grid;grid-template-columns:102px minmax(0,1fr) minmax(0,1fr) 58px;gap:10px;align-items:start;background:#19232c;border:1px solid #2c3a44;border-radius:9px;padding:11px;font-size:12px}.check>span:first-child{font-weight:700}.check .actual,.check .required{color:#b8c7ce;overflow-wrap:anywhere}.check .required:before{content:'Required · ';color:#758b95}.check .actual:before{content:'Yours · ';color:#758b95}.check em{font:800 10px Consolas,monospace;text-transform:uppercase;text-align:center;font-style:normal;border-radius:20px;padding:4px 5px}.sourcebox{border-top:1px solid var(--line);padding-top:17px;margin-top:17px}.sourcebox summary{cursor:pointer;color:var(--blue);font-weight:700;font-size:12px}.sourcebox pre{font:12px/1.5 'Segoe UI',sans-serif;white-space:pre-wrap;word-break:break-word;color:var(--muted);margin:12px 0 0}.sourcebox a{display:inline-block;margin-top:12px;font-size:12px}.foot{border-top:1px solid var(--line);color:var(--muted);font-size:12px;line-height:1.6;padding:25px 0 50px;margin-top:35px}.foot b{color:var(--text)}.hidden{display:none!important}@media(max-width:1050px){.library{grid-template-columns:minmax(290px,.85fr) minmax(400px,1.15fr)}.check{grid-template-columns:85px 1fr 1fr 48px;gap:6px}}@media(max-width:800px){.library{display:block}.listpane{min-height:0}.gamelist{max-height:440px}.detailpane{position:static;max-height:none;margin-top:15px}.hardware{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.wrap{padding:0 16px}.topnote{display:none}.hero{display:block;padding:43px 0 27px}.heroScore{border-left:0;border-top:1px solid var(--line);padding:14px 0 0;margin-top:22px}.heroScore strong{font-size:42px}.hardware{grid-template-columns:1fr}.intro{display:block}.intro p{margin-top:7px}.library{margin:0 -4px}.detailbody{padding:17px}.check{grid-template-columns:70px 1fr 1fr;gap:5px}.check em{grid-column:3}.row{grid-template-columns:27px minmax(0,1fr) auto;padding:11px}}@media print{body{background:white;color:#111}.top{position:static;background:white}.hardware>div,.listpane,.detailpane,.row,.check{background:white;color:#111;border-color:#aaa}.hero h1 span,.heroScore strong{color:#477000}.listpane{display:none}.detailpane{max-height:none}.cover{display:none}.foot{color:#444}}
"""


SCRIPT = r"""
const data = JSON.parse(document.getElementById('game-data').textContent);
const list = document.getElementById('game-list');
const detail = document.getElementById('detail');
let current = data.games[0]?.id ?? null;
let tier = data.games[0]?.recommended ? 'recommended' : 'minimum';
const labels = {meets:'Recommended',review:'Review',minimum:'Min. only',below:'Below rec.',unavailable:'No data'};
const statusLabel = {pass:'Pass',fail:'Below',review:'Review',na:'—'};
function node(tag, cls, content) { const el=document.createElement(tag); if(cls)el.className=cls; if(content!==undefined)el.textContent=content; return el; }
function visibleGames(){let q=document.getElementById('search').value.trim().toLowerCase(),cat=document.getElementById('category').value,verdict=document.getElementById('verdict').value;return data.games.filter(g=>(!q||g.name.toLowerCase().includes(q))&&(cat==='all'||g.categories.includes(cat))&&(verdict==='all'||g.verdict===verdict));}
function renderList(){let games=visibleGames();list.replaceChildren();document.getElementById('list-count').textContent=`${games.length} games shown · ${data.games.length} checked`;if(!games.length){list.append(node('div','empty','No games match these filters.'));return}for(const g of games){const row=node('button','row');row.type='button';row.setAttribute('aria-selected',String(g.id===current));row.addEventListener('click',()=>{current=g.id;tier=g.recommended?'recommended':'minimum';renderList();renderDetail();ensureDetails(g);if(matchMedia('(max-width:800px)').matches)detail.scrollIntoView({behavior:'smooth',block:'start'})});row.append(node('span','rank',g.rank?String(g.rank).padStart(2,'0'):'•'));const title=node('span','rowtitle');title.append(node('b','',g.name));title.append(node('small','',g.categories.map(c=>({popular:'Top played',new:'New release',core:'Demanding pick'})[c]).join(' · ')));row.append(title);row.append(node('span',`state ${g.verdict}`,labels[g.verdict]));list.append(row)}}
function renderDetail(){const g=data.games.find(x=>x.id===current);detail.replaceChildren();if(!g){detail.append(node('div','empty','Select a game to see its compatibility details.'));return}const cover=node('div','cover');if(g.image){const img=node('img');img.src=g.image;img.alt='';img.loading='lazy';cover.append(img)}detail.append(cover);const body=node('div','detailbody'),top=node('div','detailtop'),title=node('div');title.append(node('div','eyebrow',g.rank?`Steam weekly top played · #${g.rank}`:g.categories.includes('new')?'Steam new release':'Demanding game'));title.append(node('h2','',g.name));title.append(node('div','subline',`${g.release||'Release date unavailable'} · ${g.peak?g.peak.toLocaleString()+' weekly peak Steam players · ':''}${g.freshness==='fresh'?'Requirements fetched now':g.freshness==='stale'?'Older cached requirements':g.freshness==='snapshot'?'Built-in November 2026 snapshot':'Requirements unavailable'}`));top.append(title);top.append(node('span',`state ${g.verdict}`,labels[g.verdict]));body.append(top);body.append(node('p','desc',g.reason));const tabs=node('div','tabs');for(const choice of ['recommended','minimum']){const tab=node('button','tab',choice==='recommended'?'Recommended tier':'Minimum tier');tab.type='button';tab.setAttribute('aria-selected',String(choice===tier));tab.addEventListener('click',()=>{tier=choice;renderDetail()});tabs.append(tab)}body.append(tabs);const checks=node('div','checks');const selected=tier==='recommended'?g.recommended_checks:g.minimum_checks;for(const c of selected){const row=node('div','check');row.append(node('span','',c.label));row.append(node('span','actual',c.actual));row.append(node('span','required',c.required));row.append(node('em',c.status,c.status==='na'?'—':statusLabel[c.status]));checks.append(row)}if(!selected.length)checks.append(node('div','empty','No requirements published for this tier.'));body.append(checks);const source=node('div','sourcebox'),details=node('details'),summary=node('summary','',`Read ${tier} requirements as published`),pre=node('pre','',tier==='recommended'?(g.recommended||'Not published'):(g.minimum||'Not published'));details.append(summary,pre);source.append(details);const link=node('a','', 'Open Steam store source ↗');link.href=g.url;link.target='_blank';link.rel='noopener';source.append(link);body.append(source);detail.append(body)}
async function ensureDetails(g){
  if(!livePort || g.freshness!=='unavailable') return;
  g.reason='Checking Steam for this game…'; renderDetail();
  try {
    const response=await fetch(`http://127.0.0.1:${livePort}/game/${g.id}`,{cache:'no-store'});
    if(!response.ok) throw new Error('Steam is temporarily unavailable');
    const fresh=await response.json();
    Object.assign(g,fresh); tier=g.recommended?'recommended':'minimum';
    renderList(); renderDetail();
  } catch {
    g.reason='Live lookup is unavailable right now. Keep FrameCheck open and select this game again later, or open the Steam source.';
    renderDetail();
  }
}
for(const id of ['search','category','verdict'])document.getElementById(id).addEventListener(id==='search'?'input':'change',renderList);
renderList();renderDetail();if(data.games[0])ensureDetails(data.games[0]);
"""


def render(info, games, errors, server_port=0):
    now = datetime.now().astimezone().strftime("%d %B %Y · %H:%M %Z")
    ram = (info.get("InstalledMemory") or info["Computer"]["TotalPhysicalMemory"]) / 1024**3
    vram = f'{info["VRAMMiB"] / 1024:.0f} GB VRAM' if info.get("VRAMMiB") else "VRAM unknown"
    meets = sum(g["verdict"] == "meets" for g in games)
    review = sum(g["verdict"] == "review" for g in games)
    below = sum(g["verdict"] == "below" for g in games)
    minimum = sum(g["verdict"] == "minimum" for g in games)
    fresh_count = sum(g["freshness"] == "fresh" for g in games)
    fallback_count = sum(g["freshness"] in ("stale", "snapshot") for g in games)
    unavailable_count = sum(g["freshness"] == "unavailable" for g in games)
    payload = json.dumps({"games": games}, ensure_ascii=False, separators=(",", ":")).replace("<", "\\u003c").replace("&", "\\u0026")
    notice = f'<div class="notice"><b>Lookup issues:</b> {escape("; ".join(errors[:5]))}</div>' if errors else ""
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>FrameCheck · {escape(now)}</title><style>{STYLE}.state.minimum{{color:var(--blue);background:#243843}}</style></head><body><header class="top"><div class="wrap topin"><div class="logo">↗ FRAMECHECK / PC GAME COMPATIBILITY</div><div class="topnote">Scanned {escape(now)}</div></div></header><main class="wrap"><section class="hero"><div><div class="eyebrow">Current hardware and Steam requirements</div><h1>Your games. <span>Your machine.</span></h1><p>A searchable PC game library sourced from Steam’s weekly most played chart, new releases and demanding picks. Select a game for a component by component compatibility estimate.</p></div><div class="heroScore"><div class="eyebrow">Recommended hardware met</div><strong>{meets}<small> / {len(games)}</small></strong><p>{review} need review · {minimum} minimum only · {below} below recommended</p></div></section><section class="hardware" aria-label="Detected hardware"><div><label>Processor</label><b>{escape(info["CPU"]["Name"].strip())}</b><small>{escape(info["CPU"].get("NumberOfCores"))} cores</small></div><div><label>Graphics</label><b>{escape(info["SelectedGPU"])}</b><small>{escape(vram)}</small></div><div><label>Memory</label><b>{ram:.0f} GB RAM</b><small>Installed memory</small></div><div><label>Platform</label><b>{escape(info["OS"]["Caption"])}</b><small>{escape(info["OS"].get("OSArchitecture"))}</small></div></section><section class="intro"><h2>Game library</h2><p>Verdicts compare published PC requirements with detected hardware and available disk space. These are compatibility estimates, not measured frame rates. {fresh_count} fresh from Steam ? {fallback_count} fallback ? {unavailable_count} without requirements.</p></section>{notice}<div class="library"><section class="listpane" aria-label="Game list"><div class="listtools"><input id="search" class="search" type="search" placeholder="Search {len(games)} games" aria-label="Search games"><div class="toolrow"><select id="category" aria-label="Game category"><option value="all">All categories</option><option value="popular">Top played</option><option value="new">New releases</option><option value="core">Demanding picks</option></select><select id="verdict" aria-label="Compatibility verdict"><option value="all">All verdicts</option><option value="meets">Recommended met</option><option value="review">Needs review</option><option value="minimum">Minimum only</option><option value="below">Below recommended</option><option value="unavailable">Data unavailable</option></select></div></div><div class="listmeta" id="list-count"></div><div class="gamelist" id="game-list"></div></section><section class="detailpane" id="detail" aria-label="Selected game detail"></section></div></main><footer class="foot"><div class="wrap"><b>How this works.</b> Steam supplies the top played chart and store page PC requirements. Each scan requests current Steam requirements. Cached data is used only when a refresh fails. Nine demanding games have a clearly labelled November 2026 snapshot if Steam is unavailable. This app reads your CPU, GPU, dedicated VRAM, RAM, Windows version and free disk space when run. Model comparisons use a conservative known GPU and CPU list; unknown matches are marked for review. A published minimum or recommended tier is not a measured benchmark. To measure FPS, the game must be installed and run with a benchmark or telemetry tool. Some games also require anti-cheat or account settings that this scan does not verify.</div></footer><script type="application/json" id="game-data">{payload}</script><script>const livePort={server_port};{SCRIPT}</script></body></html>'''
